"use client";
// TEMPORARY tooth-capture harness. Replicates the EXACT single-tooth view
// (same camera framing via getSingleToothBuccalCamera, same lights, same
// [0,-0.17,0] group + Tooth props) and POSTs a transparent PNG of each tooth's
// initial view to /api/save-tooth, named by FDI. Safe to delete afterward.
import { useEffect, useState } from "react";
import * as THREE from "three";
import { Canvas, useThree } from "@react-three/fiber";
import { useGLTF } from "@react-three/drei";
import { Suspense } from "react";
import { Tooth, getFrontAzimuth } from "@/components/dental/examination/Tooth";
import { TEETH } from "@/components/dental/examination/types";

// Match the single-tooth view's framing constants from DentalCanvas.
const SINGLE_TOOTH_ORBIT_RADIUS = 6.28;
const SINGLE_TOOTH_TARGET = new THREE.Vector3(0, 0.04, 0);
const SINGLE_TOOTH_FOV = 27;
function getSingleToothBuccalCamera(fdi, width, height) {
  const aspect = width / Math.max(1, height);
  const widthFactor = (width - 980) / 980;
  const widthAdjust = Math.max(-1.1, Math.min(1.1, -widthFactor * 1.5));
  const aspectPull = aspect < 0.7 ? 2.0 : aspect < 0.9 ? 1.15 : aspect < 1.1 ? 0.6 : aspect < 1.4 ? 0.22 : 0;
  const radius = SINGLE_TOOTH_ORBIT_RADIUS + aspectPull + widthAdjust * 0.35;
  const frontAz = getFrontAzimuth(String(fdi)) ?? 0;
  const offset = new THREE.Vector3().setFromSpherical(new THREE.Spherical(radius, Math.PI / 2, frontAz));
  return {
    position: new THREE.Vector3().copy(SINGLE_TOOTH_TARGET).add(offset),
    target: SINGLE_TOOTH_TARGET.clone(),
    fov: SINGLE_TOOTH_FOV,
  };
}

// Panel size that matches the single-tooth view's CSS dimensions so the camera
// framing equals what the doctor sees.
const CSS_W = 361;
const CSS_H = 577;

function CaptureCam({ fdi }) {
  const { camera, size } = useThree();
  useEffect(() => {
    const c = getSingleToothBuccalCamera(fdi, size.width, size.height);
    camera.position.copy(c.position);
    camera.fov = c.fov;
    camera.up.set(0, 1, 0);
    camera.lookAt(c.target);
    camera.updateProjectionMatrix();
  });
  return null;
}

export default function ToothCapturePage() {
  const [idx, setIdx] = useState(0);
  const [status, setStatus] = useState("idle");

  useEffect(() => {
    TEETH.forEach((t) => { try { useGLTF.preload(t.modelPath); } catch {} });
  }, []);

  useEffect(() => {
    window.__teeth = TEETH.map((t) => t.fdi);
    window.__setTooth = (i) => setIdx(i);
    window.__progress = { i: 0, total: TEETH.length, done: false, saved: [], phase: "idle" };
    const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
    window.__runCapture = async () => {
      if (window.__capturing) return;
      window.__capturing = true;
      // Pass 1 — warm: load all GLBs + compile every shader variant in this context.
      setStatus("warming");
      window.__progress = { i: 0, total: TEETH.length, done: false, saved: [], phase: "warm" };
      for (let i = 0; i < TEETH.length; i++) { setIdx(i); window.__progress.i = i; await sleep(700); }
      await sleep(800);
      // Pass 2 — capture.
      setStatus("capturing");
      window.__progress.phase = "capture";
      for (let i = 0; i < TEETH.length; i++) {
        setIdx(i);
        window.__progress.i = i;
        await sleep(1500);
        const cv = document.querySelector("#cap-host canvas");
        let url = null;
        try { url = cv && cv.toDataURL("image/png"); } catch {}
        if (url && url.length > 5000) {
          try {
            const res = await fetch("/api/save-tooth", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ fdi: TEETH[i].fdi, dataUrl: url }),
            });
            const j = await res.json();
            if (j.ok) window.__progress.saved.push(TEETH[i].fdi);
          } catch {}
        }
      }
      window.__progress.done = true;
      window.__capturing = false;
      setStatus("done");
    };
  }, []);

  const t = TEETH[idx];
  return (
    <div style={{ padding: 20, fontFamily: "Inter, sans-serif" }}>
      <h1 style={{ fontSize: 16 }}>Tooth capture harness (single-tooth view)</h1>
      <p style={{ fontSize: 13, color: "#475569" }}>Status: {status} · current FDI: {t.fdi} ({t.name})</p>
      <button onClick={() => window.__runCapture()} style={{ padding: "8px 14px", borderRadius: 8, border: "1px solid #cbd5e1", cursor: "pointer" }}>Run capture</button>
      <div id="cap-host" style={{ width: CSS_W, height: CSS_H, marginTop: 16, background: "transparent" }}>
        <Canvas
          camera={{ position: [0, 2.5, 13], fov: 35 }}
          dpr={[2, 3]}
          gl={{ antialias: true, alpha: true, preserveDrawingBuffer: true, toneMapping: 3, toneMappingExposure: 1.3, powerPreference: "high-performance" }}
          style={{ width: "100%", height: "100%", background: "transparent" }}
        >
          <ambientLight intensity={0.8} />
          <directionalLight position={[3, 5, 4]} intensity={1.0} />
          <directionalLight position={[-2, 3, -2]} intensity={0.4} />
          <directionalLight position={[0, -2, 1]} intensity={0.3} />
          <CaptureCam fdi={t.fdi} />
          <Suspense fallback={null}>
            <group position={[0, -0.17, 0]}>
              <Tooth
                modelPath={t.modelPath}
                arch={t.arch}
                mirrorX={t.mirrorX}
                quadrant={t.quadrant}
                toothPosition={t.position}
                toothFdi={t.fdi}
                selectedZone={null}
                onSelectZone={() => {}}
                onClearSelectedZone={() => {}}
                onHoverZone={() => {}}
                isImplant={false}
                findings={[]}
                zoneNotes={{}}
                toothDiagnoses={new Set()}
                multiSelectZones={[]}
                multiSelectActive={false}
                hideTags
                treatmentHistoryDetails={{}}
                toothEntries={[]}
              />
            </group>
          </Suspense>
        </Canvas>
      </div>
    </div>
  );
}
